/** A stock-keeping item (auto part) as returned by the API. */
export interface Item {
  id: string;
  /** Human-facing code, generated by the server (e.g. `IT-00042`). */
  code: string;
  name: string;
  groupId: string;
  groupName: string;
  groupColor: string;
  unit: ItemUnit;
  barcode: string;
  brand: string;
  purchasePrice: number;
  salePrice: number;
  /** Reorder level — below it the item is flagged as low stock. */
  minStock: number;
  stock: number;
  description: string;
  isActive: boolean;
  createdAt: string;
}

export type ItemPayload = Pick<
  Item,
  'name' | 'groupId' | 'unit' | 'barcode' | 'brand' | 'purchasePrice' | 'salePrice' | 'minStock' | 'description' | 'isActive'
>;

export const ITEM_UNITS = ['قطعة', 'طقم', 'لتر', 'علبة', 'كرتونة', 'متر', 'زوج'] as const;
export type ItemUnit = (typeof ITEM_UNITS)[number];

export type StockLevel = 'out' | 'low' | 'ok';

export function stockLevel(item: Pick<Item, 'stock' | 'minStock'>): StockLevel {
  if (item.stock <= 0) return 'out';
  return item.stock <= item.minStock ? 'low' : 'ok';
}

export const STOCK_LEVEL_LABEL: Record<StockLevel, string> = {
  out: 'نفد',
  low: 'منخفض',
  ok: 'متوفر',
};

/** Gross margin as a percentage of the sale price (0 when there is no price). */
export function marginPct(purchase: number, sale: number): number {
  return sale > 0 ? Math.round(((sale - purchase) / sale) * 1000) / 10 : 0;
}
